  INSERT INTO class_subjects (class_id, subject_id) VALUES (c10_id, mat_id) ON CONFLICT DO NOTHING;
  INSERT INTO questions (school_id, subject_id, question_type, question_text, options, answer, marks, difficulty, chapters, tags, is_active) VALUES
  (sid, mat_id, 'mcq', '\(\sqrt{2}\) is a/an', '[{"key": "A", "value": "Rational number", "correct": false}, {"key": "B", "value": "Irrational number", "correct": true}, {"key": "C", "value": "Integer", "correct": false}, {"key": "D", "value": "Natural number", "correct": false}]', 'B', 1, 'easy', '["Real Numbers"]', '["number_classification"]', true),
  (sid, mat_id, 'mcq', '\(5\sqrt{3}\) is a/an', '[{"key": "A", "value": "Irrational number", "correct": true}, {"key": "B", "value": "Rational number", "correct": false}, {"key": "C", "value": "Composite number", "correct": false}, {"key": "D", "value": "Prime number", "correct": false}]', 'A', 1, 'easy', '["Real Numbers"]', '["number_classification"]', true),
  (sid, mat_id, 'mcq', 'The rational number in the following is', '[{"key": "A", "value": "\\(5\\)", "correct": true}, {"key": "B", "value": "\\(\\pi\\)", "correct": false}, {"key": "C", "value": "\\(\\sqrt{3}\\)", "correct": false}, {"key": "D", "value": "\\(3\\sqrt{3}\\)", "correct": false}]', 'A', 1, 'easy', '["Real Numbers"]', '["number_classification"]', true),
  (sid, mat_id, 'mcq', 'Which of the following is not an irrational number?', '[{"key": "A", "value": "\\(\\sqrt{2}\\)", "correct": false}, {"key": "B", "value": "\\(\\sqrt{3}\\)", "correct": false}, {"key": "C", "value": "\\(\\sqrt{9}\\)", "correct": true}, {"key": "D", "value": "\\(\\sqrt{5}\\)", "correct": false}]', 'C', 1, 'easy', '["Real Numbers"]', '["number_classification"]', true),
  (sid, mat_id, 'mcq', 'The rational number in the following is', '[{"key": "A", "value": "\\(\\sqrt{3}\\)", "correct": false}, {"key": "B", "value": "\\(\\sqrt{4}\\)", "correct": true}, {"key": "C", "value": "\\(\\sqrt{5}\\)", "correct": false}, {"key": "D", "value": "\\(\\sqrt{7}\\)", "correct": false}]', 'B', 1, 'easy', '["Real Numbers"]', '["number_classification"]', true),
  (sid, mat_id, 'mcq', '\(\pi\) is a/an', '[{"key": "A", "value": "Irrational number", "correct": true}, {"key": "B", "value": "Rational number", "correct": false}, {"key": "C", "value": "Prime number", "correct": false}, {"key": "D", "value": "Composite number", "correct": false}]', 'A', 1, 'easy', '["Real Numbers"]', '["number_classification"]', true),
  (sid, mat_id, 'mcq', 'The number \(7 \times 11 \times 13 + 13\) is a/an', '[{"key": "A", "value": "Prime number", "correct": false}, {"key": "B", "value": "Composite number", "correct": true}, {"key": "C", "value": "Irrational number", "correct": false}, {"key": "D", "value": "Odd number", "correct": false}]', 'B', 1, 'medium', '["Real Numbers"]', '["number_classification"]', true),
  (sid, mat_id, 'mcq', 'Prime factorization of \(91\) is', '[{"key": "A", "value": "\\(2 \\times 13 \\times 7\\)", "correct": false}, {"key": "B", "value": "\\(13 \\times 7\\)", "correct": true}, {"key": "C", "value": "\\(91 \\times 1\\)", "correct": false}, {"key": "D", "value": "\\(13 \\times 7 \\times 1\\)", "correct": false}]', 'B', 1, 'easy', '["Real Numbers"]', '["factorization"]', true),
  (sid, mat_id, 'mcq', 'The number of primes between \(1\) and \(10\) is', '[{"key": "A", "value": "\\(2\\)", "correct": false}, {"key": "B", "value": "\\(3\\)", "correct": false}, {"key": "C", "value": "\\(4\\)", "correct": true}, {"key": "D", "value": "\\(12\\)", "correct": false}]', 'C', 1, 'easy', '["Real Numbers"]', '["prime_numbers"]', true),
  (sid, mat_id, 'mcq', 'Any composite number can be expressed as the product of', '[{"key": "A", "value": "even numbers", "correct": false}, {"key": "B", "value": "odd numbers", "correct": false}, {"key": "C", "value": "prime numbers", "correct": true}, {"key": "D", "value": "square numbers", "correct": false}]', 'C', 1, 'easy', '["Real Numbers"]', '["fundamental_theorem"]', true),
  (sid, mat_id, 'mcq', 'The prime factorization of \(120\) is', '[{"key": "A", "value": "\\(2^3 \\times 3^2 \\times 5^1\\)", "correct": false}, {"key": "B", "value": "\\(2^2 \\times 3^1 \\times 5^1\\)", "correct": false}, {"key": "C", "value": "\\(2^3 \\times 3^1 \\times 5^2\\)", "correct": false}, {"key": "D", "value": "\\(2^3 \\times 3^1 \\times 5^1\\)", "correct": true}]', 'D', 1, 'medium', '["Real Numbers"]', '["factorization"]', true),
  (sid, mat_id, 'mcq', 'The prime factors of \(30\) are', '[{"key": "A", "value": "\\(2, 3, 5\\)", "correct": true}, {"key": "B", "value": "\\(5, 3\\)", "correct": false}, {"key": "C", "value": "\\(15, 2\\)", "correct": false}, {"key": "D", "value": "\\(6, 5\\)", "correct": false}]', 'A', 1, 'easy', '["Real Numbers"]', '["factorization"]', true),
  (sid, mat_id, 'mcq', 'The L.C.M of \(2\) and \(3\) is', '[{"key": "A", "value": "\\(2\\)", "correct": false}, {"key": "B", "value": "\\(3\\)", "correct": false}, {"key": "C", "value": "\\(5\\)", "correct": false}, {"key": "D", "value": "\\(6\\)", "correct": true}]', 'D', 1, 'easy', '["Real Numbers"]', '["lcm"]', true),
  (sid, mat_id, 'mcq', 'The H.C.F of \(3\) and \(5\) is', '[{"key": "A", "value": "\\(1\\)", "correct": true}, {"key": "B", "value": "\\(3\\)", "correct": false}, {"key": "C", "value": "\\(5\\)", "correct": false}, {"key": "D", "value": "\\(15\\)", "correct": false}]', 'A', 1, 'easy', '["Real Numbers"]', '["hcf"]', true),
  (sid, mat_id, 'mcq', 'The H.C.F of any two consecutive natural numbers is', '[{"key": "A", "value": "\\(0\\)", "correct": false}, {"key": "B", "value": "\\(1\\)", "correct": true}, {"key": "C", "value": "\\(2\\)", "correct": false}, {"key": "D", "value": "\\(3\\)", "correct": false}]', 'B', 1, 'easy', '["Real Numbers"]', '["hcf"]', true),
  (sid, mat_id, 'mcq', 'The H.C.F of any two prime numbers is', '[{"key": "A", "value": "\\(0\\)", "correct": false}, {"key": "B", "value": "\\(2\\)", "correct": false}, {"key": "C", "value": "\\(1\\)", "correct": true}, {"key": "D", "value": "\\(-1\\)", "correct": false}]', 'C', 1, 'easy', '["Real Numbers"]', '["hcf"]', true),
  (sid, mat_id, 'mcq', 'If \(a\) and \(b\) are co-primes, then their L.C.M is', '[{"key": "A", "value": "\\(0\\)", "correct": false}, {"key": "B", "value": "\\(a \\times b\\)", "correct": true}, {"key": "C", "value": "\\(1\\)", "correct": false}, {"key": "D", "value": "\\(a + b\\)", "correct": false}]', 'B', 1, 'medium', '["Real Numbers"]', '["lcm"]', true),
  (sid, mat_id, 'mcq', 'The H.C.F of the smallest composite number and the smallest prime number is', '[{"key": "A", "value": "\\(4\\)", "correct": false}, {"key": "B", "value": "\\(2\\)", "correct": true}, {"key": "C", "value": "\\(1\\)", "correct": false}, {"key": "D", "value": "\\(8\\)", "correct": false}]', 'B', 1, 'medium', '["Real Numbers"]', '["hcf"]', true),
  (sid, mat_id, 'mcq', 'For any two positive integers, \(a\) and \(b\), \(\text{H.C.F}(a, b) \times \text{L.C.M}(a, b)\) is equal to', '[{"key": "A", "value": "\\((a + b)\\)", "correct": false}, {"key": "B", "value": "\\((a - b)\\)", "correct": false}, {"key": "C", "value": "\\((a \\times b)\\)", "correct": true}, {"key": "D", "value": "\\((a \\div b)\\)", "correct": false}]', 'C', 1, 'easy', '["Real Numbers"]', '["hcf_lcm_relation"]', true),
  (sid, mat_id, 'mcq', 'The H.C.F of \((12, 15)\) is \(3\). The L.C.M of \((12, 15)\) is', '[{"key": "A", "value": "\\(60\\)", "correct": true}, {"key": "B", "value": "\\(45\\)", "correct": false}, {"key": "C", "value": "\\(36\\)", "correct": false}, {"key": "D", "value": "\\(90\\)", "correct": false}]', 'A', 1, 'medium', '["Real Numbers"]', '["lcm"]', true),
  (sid, mat_id, 'mcq', 'The H.C.F of \(5^2 \times 2\) and \(2^5 \times 5\) is', '[{"key": "A", "value": "\\(2 \\times 5\\)", "correct": true}, {"key": "B", "value": "\\(2^5 \\times 5\\)", "correct": false}, {"key": "C", "value": "\\(5^2 \\times 2^5\\)", "correct": false}, {"key": "D", "value": "\\(2^5 \\times 5^2\\)", "correct": false}]', 'A', 1, 'medium', '["Real Numbers"]', '["hcf"]', true),
  (sid, mat_id, 'mcq', 'Two positive integers \(a\) and \(b\) are expressed as \(a = x^3 y^2\) and \(b = x y^3\). If \(x\) and \(y\) are prime numbers, then the H.C.F of \((a, b)\) is', '[{"key": "A", "value": "\\(x y\\)", "correct": false}, {"key": "B", "value": "\\(x y^2\\)", "correct": true}, {"key": "C", "value": "\\(x^3 y^3\\)", "correct": false}, {"key": "D", "value": "\\(x^2 y^2\\)", "correct": false}]', 'B', 1, 'hard', '["Real Numbers"]', '["hcf"]', true),
  (sid, mat_id, 'mcq', 'The L.C.M of \(a\) and \(18\) is \(36\) and the H.C.F of \(a\) and \(18\) is \(2\). The value of \(a\) is', '[{"key": "A", "value": "\\(2\\)", "correct": false}, {"key": "B", "value": "\\(3\\)", "correct": false}, {"key": "C", "value": "\\(4\\)", "correct": true}, {"key": "D", "value": "\\(1\\)", "correct": false}]', 'C', 1, 'medium', '["Real Numbers"]', '["hcf_lcm_relation"]', true),
  (sid, mat_id, 'mcq', 'If \(p\) and \(q\) are co-primes, then the H.C.F of \(p^2\) and \(q^2\) is', '[{"key": "A", "value": "\\(pq\\)", "correct": false}, {"key": "B", "value": "\\(1\\)", "correct": true}, {"key": "C", "value": "\\(p+q\\)", "correct": false}, {"key": "D", "value": "\\(p^2q^2\\)", "correct": false}]', 'B', 1, 'medium', '["Real Numbers"]', '["hcf"]', true),
  (sid, mat_id, 'mcq', 'If \(180 = 2^x \times 3^2 \times 5\) then the value of \(x\) is', '[{"key": "A", "value": "\\(1\\)", "correct": false}, {"key": "B", "value": "\\(2\\)", "correct": true}, {"key": "C", "value": "\\(3\\)", "correct": false}, {"key": "D", "value": "\\(4\\)", "correct": false}]', 'B', 1, 'medium', '["Real Numbers"]', '["factorization"]', true),
  (sid, mat_id, 'mcq', 'The product of the H.C.F and L.C.M of the numbers \(15\) and \(20\) is', '[{"key": "A", "value": "\\(15\\)", "correct": false}, {"key": "B", "value": "\\(20\\)", "correct": false}, {"key": "C", "value": "\\(300\\)", "correct": true}, {"key": "D", "value": "\\(35\\)", "correct": false}]', 'C', 1, 'easy', '["Real Numbers"]', '["hcf_lcm_relation"]', true),
  (sid, mat_id, 'mcq', '\(a\) is an odd number and \(b\) is a number divisible by \(3\). If the L.C.M of \(a\) and \(b\) is \(p\), then the L.C.M of \(3a\) and \(2b\) is', '[{"key": "A", "value": "\\(p^2\\)", "correct": false}, {"key": "B", "value": "\\(5p\\)", "correct": false}, {"key": "C", "value": "\\(6p\\)", "correct": true}, {"key": "D", "value": "\\(3p\\)", "correct": false}]', 'C', 1, 'hard', '["Real Numbers"]', '["lcm"]', true),
  (sid, mat_id, 'mcq', 'The H.C.F and L.C.M of two numbers \(a\) and \(b\) are \(5\) and \(200\) respectively. The product of \(a\) and \(b\) is', '[{"key": "A", "value": "\\(205\\)", "correct": false}, {"key": "B", "value": "\\(1000\\)", "correct": true}, {"key": "C", "value": "\\(200\\)", "correct": false}, {"key": "D", "value": "\\(195\\)", "correct": false}]', 'B', 1, 'easy', '["Real Numbers"]', '["hcf_lcm_relation"]', true),
  (sid, mat_id, 'mcq', 'The degree of the polynomial \(p(x) = x^2 - 3x + 4x^3 - 6\) is', '[{"key": "A", "value": "\\(2\\)", "correct": false}, {"key": "B", "value": "\\(1\\)", "correct": false}, {"key": "C", "value": "\\(3\\)", "correct": true}, {"key": "D", "value": "\\(6\\)", "correct": false}]', 'C', 1, 'easy', '["Polynomials"]', '["polynomial_degree"]', true),
  (sid, mat_id, 'mcq', 'The degree of a linear polynomial is', '[{"key": "A", "value": "\\(0\\)", "correct": false}, {"key": "B", "value": "\\(1\\)", "correct": true}, {"key": "C", "value": "\\(2\\)", "correct": false}, {"key": "D", "value": "\\(3\\)", "correct": false}]', 'B', 1, 'easy', '["Polynomials"]', '["polynomial_degree"]', true),
  (sid, mat_id, 'mcq', 'The degree of the polynomial \(p(x) = 2x^3 + 3x - 11 + 6\) is', '[{"key": "A", "value": "\\(2\\)", "correct": false}, {"key": "B", "value": "\\(6\\)", "correct": false}, {"key": "C", "value": "\\(3\\)", "correct": true}, {"key": "D", "value": "\\(4\\)", "correct": false}]', 'C', 1, 'easy', '["Polynomials"]', '["polynomial_degree"]', true),
  (sid, mat_id, 'mcq', 'The degree of a quadratic polynomial is', '[{"key": "A", "value": "\\(4\\)", "correct": false}, {"key": "B", "value": "\\(1\\)", "correct": false}, {"key": "C", "value": "\\(2\\)", "correct": true}, {"key": "D", "value": "\\(3\\)", "correct": false}]', 'C', 1, 'easy', '["Polynomials"]', '["polynomial_degree"]', true),
  (sid, mat_id, 'mcq', 'The degree of a cubic polynomial is', '[{"key": "A", "value": "\\(4\\)", "correct": false}, {"key": "B", "value": "\\(1\\)", "correct": false}, {"key": "C", "value": "\\(3\\)", "correct": true}, {"key": "D", "value": "\\(2\\)", "correct": false}]', 'C', 1, 'easy', '["Polynomials"]', '["polynomial_degree"]', true),
  (sid, mat_id, 'mcq', 'The maximum number of zeroes of a quadratic polynomial is', '[{"key": "A", "value": "\\(4\\)", "correct": false}, {"key": "B", "value": "\\(1\\)", "correct": false}, {"key": "C", "value": "\\(2\\)", "correct": true}, {"key": "D", "value": "\\(3\\)", "correct": false}]', 'C', 1, 'easy', '["Polynomials"]', '["polynomial_zeroes"]', true),
  (sid, mat_id, 'mcq', 'In the quadratic polynomial \(f(x) = x^2 - 9x + 20\), the value of \(f(0)\) is', '[{"key": "A", "value": "\\(20\\)", "correct": true}, {"key": "B", "value": "\\(11\\)", "correct": false}, {"key": "C", "value": "\\(-20\\)", "correct": false}, {"key": "D", "value": "\\(29\\)", "correct": false}]', 'A', 1, 'easy', '["Polynomials"]', '["polynomial_evaluation"]', true),
  (sid, mat_id, 'mcq', 'In the polynomial \(p(x) = x^2 - 1\), the value of \(p(2)\) is', '[{"key": "A", "value": "\\(2\\)", "correct": false}, {"key": "B", "value": "\\(3\\)", "correct": true}, {"key": "C", "value": "\\(0\\)", "correct": false}, {"key": "D", "value": "\\(1\\)", "correct": false}]', 'B', 1, 'easy', '["Polynomials"]', '["polynomial_evaluation"]', true),
  (sid, mat_id, 'mcq', 'The quadratic polynomial whose sum and product of the zeroes are \(-2\) and \(8\) is', '[{"key": "A", "value": "\\(x^2 + 2x + 8\\)", "correct": true}, {"key": "B", "value": "\\(x^2 - 2x - 8\\)", "correct": false}, {"key": "C", "value": "\\(x^2 + 2x - 8\\)", "correct": false}, {"key": "D", "value": "\\(x^2 - 2x + 8\\)", "correct": false}]', 'A', 1, 'medium', '["Polynomials"]', '["polynomial_formation"]', true),
  (sid, mat_id, 'mcq', 'If \(\alpha\) and \(\beta\) are the zeroes of the polynomial \(p(x) = ax^2 + bx + c\), then the value of \(\alpha \times \beta\) is', '[{"key": "A", "value": "\\(\\frac{b}{a}\\)", "correct": false}, {"key": "B", "value": "\\(\\frac{-b}{a}\\)", "correct": false}, {"key": "C", "value": "\\(\\frac{c}{a}\\)", "correct": true}, {"key": "D", "value": "\\(\\frac{-c}{a}\\)", "correct": false}]', 'C', 1, 'easy', '["Polynomials"]', '["zero_coefficient_relation"]', true),
  (sid, mat_id, 'mcq', 'If \(\alpha\) and \(\beta\) are the zeroes of the polynomial \(p(x) = ax^2 + bx + c\), then the value of \(\alpha + \beta\) is', '[{"key": "A", "value": "\\(\\frac{b}{a}\\)", "correct": false}, {"key": "B", "value": "\\(\\frac{-b}{a}\\)", "correct": true}, {"key": "C", "value": "\\(\\frac{c}{a}\\)", "correct": false}, {"key": "D", "value": "\\(\\frac{-c}{a}\\)", "correct": false}]', 'B', 1, 'easy', '["Polynomials"]', '["zero_coefficient_relation"]', true),
  (sid, mat_id, 'mcq', 'If one of the zeroes of the polynomial \(p(x) = x^2 - x + k\) is \(2\), then the value of \(k\) is', '[{"key": "A", "value": "\\(2\\)", "correct": false}, {"key": "B", "value": "\\(-2\\)", "correct": true}, {"key": "C", "value": "\\(-6\\)", "correct": false}, {"key": "D", "value": "\\(6\\)", "correct": false}]', 'B', 1, 'medium', '["Polynomials"]', '["polynomial_zeroes"]', true),
  (sid, mat_id, 'mcq', 'If the sum of the zeroes of the polynomial \(p(x) = kx^2 + 2x + 3k\) is equal to the product of its zeroes, then the value of \(k\) is', '[{"key": "A", "value": "\\(\\frac{2}{3}\\)", "correct": false}, {"key": "B", "value": "\\(\\frac{-2}{3}\\)", "correct": true}, {"key": "C", "value": "\\(\\frac{3}{4}\\)", "correct": false}, {"key": "D", "value": "\\(\\frac{-3}{4}\\)", "correct": false}]', 'B', 1, 'hard', '["Polynomials"]', '["zero_coefficient_relation"]', true),
  (sid, mat_id, 'mcq', 'The quadratic polynomial whose sum and product of the zeroes are \(4\) and \(5\) respectively is', '[{"key": "A", "value": "\\(p(x) = x^2 - 4x - 5\\)", "correct": false}, {"key": "B", "value": "\\(p(x) = x^2 + 4x - 5\\)", "correct": false}, {"key": "C", "value": "\\(p(x) = x^2 - 5x + 4\\)", "correct": false}, {"key": "D", "value": "\\(p(x) = x^2 - 4x + 5\\)", "correct": true}]', 'D', 1, 'medium', '["Polynomials"]', '["polynomial_formation"]', true),
  (sid, mat_id, 'mcq', 'The sum of the zeroes of the polynomial \(p(x) = x^2 - 2x - 8\) is', '[{"key": "A", "value": "\\(-8\\)", "correct": false}, {"key": "B", "value": "\\(2\\)", "correct": true}, {"key": "C", "value": "\\(-2\\)", "correct": false}, {"key": "D", "value": "\\(8\\)", "correct": false}]', 'B', 1, 'easy', '["Polynomials"]', '["zero_coefficient_relation"]', true),
  (sid, mat_id, 'mcq', 'If the graph of a polynomial \(P(x)\) passes through the coordinate points \((-3, 0)\), \((-1, -5)\), \((0, -6)\) and \((2, 0)\), then the zeroes of the polynomial are', '[{"key": "A", "value": "\\(-3\\) and \\(-6\\)", "correct": false}, {"key": "B", "value": "\\(0\\) and \\(-3\\)", "correct": false}, {"key": "C", "value": "\\(-1\\) and \\(-5\\)", "correct": false}, {"key": "D", "value": "\\(-3\\) and \\(2\\)", "correct": true}]', 'D', 1, 'hard', '["Polynomials"]', '["graphical_zeroes"]', true),
  (sid, mat_id, 'mcq', 'If the lines drawn for the pair of linear equations \(a_1x + b_1y + c_1 = 0\) and \(a_2x + b_2y + c_2 = 0\) are coincident, then the correct relation among the following is', '[{"key": "A", "value": "\\(\\frac{a_1}{a_2} = \\frac{b_1}{b_2} = \\frac{c_1}{c_2}\\)", "correct": true}, {"key": "B", "value": "\\(\\frac{a_1}{a_2} \\neq \\frac{b_1}{b_2} \\neq \\frac{c_1}{c_2}\\)", "correct": false}, {"key": "C", "value": "\\(\\frac{a_1}{a_2} = \\frac{b_1}{b_2} \\neq \\frac{c_1}{c_2}\\)", "correct": false}, {"key": "D", "value": "\\(\\frac{a_1}{a_2} \\neq \\frac{b_1}{b_2} = \\frac{c_1}{c_2}\\)", "correct": false}]', 'A', 1, 'easy', '["Pair of Linear Equations in Two Variables"]', '["consistency_conditions"]', true),
  (sid, mat_id, 'mcq', 'If the lines drawn for the pair of linear equations \(a_1x + b_1y + c_1 = 0\) and \(a_2x + b_2y + c_2 = 0\) are intersecting, then the correct relation among the following is', '[{"key": "A", "value": "\\(\\frac{a_1}{a_2} = \\frac{b_1}{b_2} \\neq \\frac{c_1}{c_2}\\)", "correct": false}, {"key": "B", "value": "\\(\\frac{a_1}{a_2} = \\frac{b_1}{b_2} = \\frac{c_1}{c_2}\\)", "correct": false}, {"key": "C", "value": "\\(\\frac{a_1}{a_2} \\neq \\frac{b_1}{b_2}\\)", "correct": true}, {"key": "D", "value": "\\(\\frac{a_1}{b_2} = \\frac{b_1}{a_2}\\)", "correct": false}]', 'C', 1, 'easy', '["Pair of Linear Equations in Two Variables"]', '["consistency_conditions"]', true),
  (sid, mat_id, 'mcq', 'In the pair of linear equations, \(a_1x + b_1y + c_1 = 0\) and \(a_2x + b_2y + c_2 = 0\), if \(\frac{a_1}{a_2} \neq \frac{b_1}{b_2}\) then', '[{"key": "A", "value": "The equations do not have any solution", "correct": false}, {"key": "B", "value": "The equations have a unique solution", "correct": true}, {"key": "C", "value": "The equations have three solutions", "correct": false}, {"key": "D", "value": "The equations have infinitely many solutions", "correct": false}]', 'B', 1, 'easy', '["Pair of Linear Equations in Two Variables"]', '["consistency_conditions"]', true),
  (sid, mat_id, 'mcq', 'If the pair of linear equations \(a_1x + b_1y + c_1 = 0\) and \(a_2x + b_2y + c_2 = 0\) have a unique solution, then the correct relation among the following is', '[{"key": "A", "value": "\\(\\frac{a_1}{a_2} \\neq \\frac{b_1}{b_2}\\)", "correct": true}, {"key": "B", "value": "\\(\\frac{a_1}{a_2} = \\frac{b_1}{b_2} = \\frac{c_1}{c_2}\\)", "correct": false}, {"key": "C", "value": "\\(\\frac{a_1}{a_2} = \\frac{b_1}{b_2}\\)", "correct": false}, {"key": "D", "value": "\\(\\frac{a_1}{a_2} = \\frac{b_1}{b_2} \\neq \\frac{c_1}{c_2}\\)", "correct": false}]', 'A', 1, 'easy', '["Pair of Linear Equations in Two Variables"]', '["consistency_conditions"]', true),
  (sid, mat_id, 'mcq', 'The lines representing the equations \(2x + 3y - 9 = 0\) and \(4x + 6y - 18 = 0\) are', '[{"key": "A", "value": "Intersecting lines", "correct": false}, {"key": "B", "value": "Perpendicular to each other", "correct": false}, {"key": "C", "value": "Parallel lines", "correct": false}, {"key": "D", "value": "Coincident lines", "correct": true}]', 'D', 1, 'medium', '["Pair of Linear Equations in Two Variables"]', '["linear_systems_classification"]', true),
  (sid, mat_id, 'mcq', 'The lines representing the equations \(x + 2y - 4 = 0\) and \(2x + 4y - 12 = 0\) are', '[{"key": "A", "value": "Intersecting lines", "correct": false}, {"key": "B", "value": "Parallel lines", "correct": true}, {"key": "C", "value": "Perpendicular to each other", "correct": false}, {"key": "D", "value": "Coincident lines", "correct": false}]', 'B', 1, 'medium', '["Pair of Linear Equations in Two Variables"]', '["linear_systems_classification"]', true),
