  (sid, mat_id, 'mcq', 'In a circle with centre \(O\), \(AC\) is a tangent at \(A\). If \(OC = 4\text{ cm}\) and \(\angle ACO = 30^\circ\), then the radius of the circle is', '[{"key": "A", "value": "\\(\\sqrt{3}\\text{ cm}\\)", "correct": false}, {"key": "B", "value": "\\(4\\sqrt{3}\\text{ cm}\\)", "correct": false}, {"key": "C", "value": "\\(2\\text{ cm}\\)", "correct": true}, {"key": "D", "value": "\\(3\\text{ cm}\\)", "correct": false}]', 'C', 1, 'hard', '["Some Applications of Trigonometry"]', '["heights_distances"]', true),
  (sid, mat_id, 'mcq', 'In a circle, a line segment intersecting the circle at two points is called a', '[{"key": "A", "value": "chord", "correct": false}, {"key": "B", "value": "secant", "correct": true}, {"key": "C", "value": "tangent", "correct": false}, {"key": "D", "value": "radius", "correct": false}]', 'B', 1, 'easy', '["Circles"]', '["circle_definitions"]', true),
